package restudio.reglassneo.mixin.client;

import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.LoadingOverlay;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.Overwrite;import org.spongepowered.asm.mixin.Shadow;import restudio.reglassneo.client.api.WidgetStyle;import restudio.reglassneo.client.render.LiquidGlassRenderer;
@Mixin(LoadingOverlay.class)public abstract class LoadingOverlayMixin {@Shadow private float currentProgress;@Overwrite public void render(GuiGraphics g,int mouseX,int mouseY,float partialTick){int w=g.guiWidth(),h=g.guiHeight();float p=Math.max(0f,Math.min(1f,currentProgress));g.fill(0,0,w,h,0xFF101217);int bw=Math.min(420,Math.max(240,w-96)),bh=20,x=(w-bw)/2,y=h/2+42;WidgetStyle s=WidgetStyle.create().tint(0xFFFFFF,.12f).shadow(34f,.34f,0f,4f).shadowColor(0x000000,.92f).smoothing(.05f);LiquidGlassRenderer.renderCapsule(g,x,y,bw,bh,p,s);g.drawCenteredString(Minecraft.getInstance().font,"ReGlassNeo",w/2,y-30,0xFFFFFFFF);g.drawCenteredString(Minecraft.getInstance().font,Math.round(p*100f)+"%",w/2,y+30,0xFFD9DCE4);}}
